
// =========================================================
// LUTMIN V5.0 · PORTAL DOCENTE + ACTIVIDADES + CHECK-IN
// =========================================================
let adminInstructorV50={users:[],instructors:[],groups:[]};
let instructorPortalV50={profile:null,summary:{},groups:[]};
let studentActivitiesV50={summary:{},activities:[]};
let instructorTabV50='overview';
let instructorActiveSessionV50=null;
let instructorActiveActivityV50=null;

function v50Date(value){if(!value)return '—';try{return new Date(value).toLocaleDateString('es-AR');}catch(_){return String(value)}}
function v50DateTime(value){if(!value)return '—';try{return new Date(value).toLocaleString('es-AR',{dateStyle:'short',timeStyle:'short'});}catch(_){return String(value)}}
function v50Time(value){if(!value)return '';return String(value).slice(0,5)}
function v50GroupById(id){return (instructorPortalV50.groups||[]).find(g=>g.id===id)}
function v50ActivityById(id){for(const g of instructorPortalV50.groups||[]){const a=(g.activities||[]).find(x=>x.id===id);if(a)return {...a,group:g};}return null}
function v50SessionById(id){for(const g of instructorPortalV50.groups||[]){const s=(g.sessions||[]).find(x=>x.id===id);if(s)return {...s,group:g};}return null}
function v50AttendancePct(group,memberId){let marked=0,ok=0;for(const s of group.sessions||[]){const a=(s.attendance||[]).find(x=>x.user_id===memberId);if(a&&a.status&&a.status!=='pending'){marked++;if(['present','late'].includes(a.status))ok++;}}return marked?Math.round(ok*100/marked):null}
function v50DueMeta(value){if(!value)return {label:'Sin fecha límite',cls:'text-slate-400'};const d=Math.ceil((new Date(value)-Date.now())/86400000);if(d<0)return {label:`Venció hace ${Math.abs(d)} día${Math.abs(d)===1?'':'s'}`,cls:'text-red-600'};if(d===0)return {label:'Vence hoy',cls:'text-red-600'};if(d<=3)return {label:`Vence en ${d} día${d===1?'':'s'}`,cls:'text-amber-600'};return {label:`Vence ${v50Date(value)}`,cls:'text-slate-500'};}

// ---------------------------------------------------------
// ADMIN · gestión de docentes
// ---------------------------------------------------------
function initAdminInstructorV50(){
  const anchor=document.getElementById('adminAcademyOpsV36')||document.getElementById('adminAcademicV25')||document.querySelector('[data-admin-module-v19="academic"]');
  if(!anchor||document.getElementById('adminInstructorCenterV50'))return;
  const block=document.createElement('div');
  block.id='adminInstructorCenterV50';
  block.setAttribute('data-admin-module-v19','academic');
  block.className='mt-6 bg-white rounded-3xl border border-emerald-100 overflow-hidden';
  block.innerHTML=`<div class="p-5 sm:p-6 border-b border-emerald-100 bg-emerald-50/50"><div class="flex flex-col xl:flex-row xl:items-end xl:justify-between gap-4"><div><p class="text-[10px] uppercase tracking-widest font-extrabold text-emerald-700">V5.0 · Portal Docente</p><h3 class="mt-1 text-xl font-black text-lutmin-dark">Docentes y comisiones</h3><p class="mt-1 text-xs text-slate-600">Habilitá cuentas docentes, asignalas a comisiones y definí qué pueden gestionar.</p></div><button onclick="loadAdminInstructorV50()" class="px-3 py-2.5 rounded-xl bg-lutmin-dark text-white text-xs font-bold"><i class="fa-solid fa-rotate mr-2"></i>Actualizar</button></div></div><div id="adminInstructorBodyV50" class="p-5 sm:p-6"><p class="text-sm text-slate-500">Cargando docentes...</p></div>`;
  anchor.insertAdjacentElement('afterend',block);
}

async function loadAdminInstructorV50(){
  if(!supabaseClient||currentLutminUser?.role!=='admin')return;
  initAdminInstructorV50();
  const root=document.getElementById('adminInstructorBodyV50');if(root)root.innerHTML='<p class="text-sm text-slate-500"><i class="fa-solid fa-spinner fa-spin mr-2"></i>Cargando docentes...</p>';
  const {data,error}=await supabaseClient.rpc('admin_instructor_center_v50');
  if(error){console.error('V5 docentes admin',error);if(root)root.innerHTML='<div class="rounded-2xl bg-amber-50 border border-amber-100 p-4 text-sm text-amber-800">El Portal Docente todavía no está habilitado. Contactá a Administración.</div>';return;}
  adminInstructorV50=data||{users:[],instructors:[],groups:[]};
  renderAdminInstructorV50();
}

function renderAdminInstructorV50(){
  const root=document.getElementById('adminInstructorBodyV50');if(!root)return;
  const users=adminInstructorV50.users||[],instructors=adminInstructorV50.instructors||[],groups=adminInstructorV50.groups||[];
  root.innerHTML=`<div class="grid xl:grid-cols-[.9fr_1.1fr] gap-5">
    <div class="space-y-4">
      <form onsubmit="saveInstructorV50(event)" class="rounded-2xl border border-slate-100 p-4 sm:p-5">
        <div class="flex items-center gap-3"><div class="w-10 h-10 rounded-xl bg-emerald-50 text-emerald-700 flex items-center justify-center"><i class="fa-solid fa-chalkboard-user"></i></div><div><h4 class="font-extrabold text-lutmin-dark">Habilitar / editar docente</h4><p class="text-xs text-slate-500">Usá una cuenta existente de Lutmin.</p></div></div>
        <input id="v50InstructorEditId" type="hidden">
        <select id="v50InstructorUser" required class="mt-4 w-full px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm"><option value="">Elegir usuario</option>${users.map(u=>`<option value="${u.id}">${escapeHtml(u.full_name||u.email||'Usuario')} · ${escapeHtml(u.email||'')}</option>`).join('')}</select>
        <input id="v50InstructorSpecialties" class="mt-3 w-full px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm" placeholder="Especialidades separadas por coma">
        <textarea id="v50InstructorBio" rows="3" class="mt-3 w-full px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm" placeholder="Perfil / experiencia docente"></textarea>
        <div class="mt-3 grid sm:grid-cols-3 gap-2 text-xs"><label class="rounded-xl bg-slate-50 p-3 flex items-center gap-2"><input id="v50CanSessions" type="checkbox" checked> Gestionar jornadas</label><label class="rounded-xl bg-slate-50 p-3 flex items-center gap-2"><input id="v50CanAttendance" type="checkbox" checked> Asistencia</label><label class="rounded-xl bg-slate-50 p-3 flex items-center gap-2"><input id="v50CanGrade" type="checkbox" checked> Actividades / notas</label></div>
        <button class="mt-4 w-full py-2.5 rounded-xl bg-emerald-600 text-white text-xs font-extrabold">Guardar acceso docente</button>
      </form>
      <form onsubmit="assignInstructorGroupV50(event)" class="rounded-2xl border border-slate-100 p-4 sm:p-5">
        <h4 class="font-extrabold text-lutmin-dark">Asignar a una comisión</h4><div class="mt-3 grid sm:grid-cols-2 gap-2"><select id="v50AssignInstructor" required class="px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-xs"><option value="">Docente</option>${instructors.filter(i=>i.active!==false).map(i=>`<option value="${i.user_id}">${escapeHtml(i.full_name||i.email)}</option>`).join('')}</select><select id="v50AssignGroup" required class="px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-xs"><option value="">Comisión</option>${groups.map(g=>`<option value="${g.id}">${escapeHtml(g.name)} · ${escapeHtml(g.course_title||'Curso')}</option>`).join('')}</select><select id="v50AssignRole" class="px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-xs"><option value="lead">Docente principal</option><option value="assistant">Asistente</option></select><button class="px-3 py-2.5 rounded-xl bg-lutmin-dark text-white text-xs font-bold">Asignar</button></div>
      </form>
    </div>
    <div class="rounded-2xl border border-slate-100 overflow-hidden"><div class="p-4 border-b border-slate-100"><h4 class="font-extrabold text-lutmin-dark">Docentes habilitados</h4><p class="text-xs text-slate-500">${instructors.filter(i=>i.active!==false).length} activos.</p></div><div class="divide-y divide-slate-100">${instructors.length?instructors.map(i=>`<div class="p-4"><div class="flex flex-col lg:flex-row lg:items-start lg:justify-between gap-3"><div><p class="font-extrabold text-sm text-lutmin-dark">${escapeHtml(i.full_name||i.email||'Docente')}</p><p class="text-[10px] text-slate-400">${escapeHtml(i.email||'')}</p>${(i.specialties||[]).length?`<div class="mt-2 flex flex-wrap gap-1">${i.specialties.map(x=>`<span class="px-2 py-1 rounded-lg bg-emerald-50 text-emerald-700 text-[9px] font-bold">${escapeHtml(x)}</span>`).join('')}</div>`:''}</div><div class="flex gap-2"><button onclick="editInstructorV50('${i.user_id}')" class="px-3 py-2 rounded-xl bg-slate-100 text-xs font-bold">Editar</button>${i.active!==false?`<button onclick="setInstructorActiveV50('${i.user_id}',false)" class="px-3 py-2 rounded-xl bg-red-50 text-red-700 text-xs font-bold">Desactivar</button>`:`<button onclick="setInstructorActiveV50('${i.user_id}',true)" class="px-3 py-2 rounded-xl bg-emerald-50 text-emerald-700 text-xs font-bold">Reactivar</button>`}</div></div><div class="mt-3 space-y-1">${(i.groups||[]).length?(i.groups||[]).map(g=>`<div class="rounded-xl bg-slate-50 px-3 py-2 flex items-center justify-between gap-3"><span class="text-[10px] font-bold text-slate-700">${escapeHtml(g.group_name)} · ${escapeHtml(g.course_title||'Curso')} <span class="text-slate-400">· ${g.assignment_role==='assistant'?'Asistente':'Principal'}</span></span><button onclick="removeInstructorGroupV50('${i.user_id}','${g.group_id}','${g.assignment_role}')" class="text-red-400"><i class="fa-solid fa-xmark"></i></button></div>`).join(''):'<p class="text-[10px] text-slate-400">Sin comisiones asignadas.</p>'}</div></div>`).join(''):'<div class="p-6 text-sm text-slate-500">Todavía no hay docentes habilitados.</div>'}</div></div>
  </div>`;
}

function editInstructorV50(userId){const i=(adminInstructorV50.instructors||[]).find(x=>x.user_id===userId);if(!i)return;document.getElementById('v50InstructorEditId').value=userId;document.getElementById('v50InstructorUser').value=userId;document.getElementById('v50InstructorSpecialties').value=(i.specialties||[]).join(', ');document.getElementById('v50InstructorBio').value=i.bio||'';document.getElementById('v50CanSessions').checked=i.can_manage_sessions!==false;document.getElementById('v50CanAttendance').checked=i.can_mark_attendance!==false;document.getElementById('v50CanGrade').checked=i.can_grade!==false;document.getElementById('v50InstructorUser').scrollIntoView({behavior:'smooth',block:'center'});}
async function saveInstructorV50(e){e.preventDefault();const userId=document.getElementById('v50InstructorUser').value;if(!userId)return;const {error}=await supabaseClient.rpc('admin_set_instructor_v50',{p_user_id:userId,p_active:true,p_bio:document.getElementById('v50InstructorBio').value||null,p_specialties:document.getElementById('v50InstructorSpecialties').value||null,p_can_manage_sessions:document.getElementById('v50CanSessions').checked,p_can_mark_attendance:document.getElementById('v50CanAttendance').checked,p_can_grade:document.getElementById('v50CanGrade').checked});if(error)return showToast(error.message||'No pude guardar el docente.');showToast('Acceso docente guardado.');e.target.reset();await loadAdminInstructorV50();}
async function setInstructorActiveV50(userId,active){const i=(adminInstructorV50.instructors||[]).find(x=>x.user_id===userId)||{};const {error}=await supabaseClient.rpc('admin_set_instructor_v50',{p_user_id:userId,p_active:active,p_bio:i.bio||null,p_specialties:(i.specialties||[]).join(', '),p_can_manage_sessions:i.can_manage_sessions!==false,p_can_mark_attendance:i.can_mark_attendance!==false,p_can_grade:i.can_grade!==false});if(error)return showToast(error.message||'No pude actualizar el acceso.');showToast(active?'Docente reactivado.':'Docente desactivado.');await loadAdminInstructorV50();}
async function assignInstructorGroupV50(e){e.preventDefault();const {error}=await supabaseClient.rpc('admin_assign_instructor_group_v50',{p_user_id:document.getElementById('v50AssignInstructor').value,p_group_id:document.getElementById('v50AssignGroup').value,p_role:document.getElementById('v50AssignRole').value,p_active:true});if(error)return showToast(error.message||'No pude asignar la comisión.');showToast('Comisión asignada al docente.');await loadAdminInstructorV50();}
async function removeInstructorGroupV50(userId,groupId,role){if(!confirm('¿Quitar esta comisión del acceso docente?'))return;const {error}=await supabaseClient.rpc('admin_assign_instructor_group_v50',{p_user_id:userId,p_group_id:groupId,p_role:role||'lead',p_active:false});if(error)return showToast(error.message||'No pude quitar la comisión.');showToast('Comisión quitada.');await loadAdminInstructorV50();}

// ---------------------------------------------------------
// PORTAL DOCENTE
// ---------------------------------------------------------
function renderInstructorSummaryV50(){const root=document.getElementById('instructorSummaryV50');if(!root)return;const s=instructorPortalV50.summary||{};root.innerHTML=`<div class="bg-white rounded-2xl border border-slate-100 p-5"><p class="text-[10px] font-bold text-slate-400">COMISIONES</p><p class="mt-2 text-3xl font-black text-lutmin-dark">${Number(s.groups||0)}</p></div><div class="bg-white rounded-2xl border border-slate-100 p-5"><p class="text-[10px] font-bold text-slate-400">ALUMNOS</p><p class="mt-2 text-3xl font-black text-blue-600">${Number(s.students||0)}</p></div><div class="bg-white rounded-2xl border border-slate-100 p-5"><p class="text-[10px] font-bold text-slate-400">PRÓXIMAS JORNADAS</p><p class="mt-2 text-3xl font-black text-emerald-600">${Number(s.upcoming_sessions||0)}</p></div><div class="bg-white rounded-2xl border border-slate-100 p-5"><p class="text-[10px] font-bold text-slate-400">ENTREGAS A REVISAR</p><p class="mt-2 text-3xl font-black text-amber-600">${Number(s.pending_reviews||0)}</p></div>`;}
function renderInstructorTabsV50(){const root=document.getElementById('instructorTabsV50');if(!root)return;const tabs=[['overview','Resumen','fa-house'],['agenda','Agenda y asistencia','fa-calendar-check'],['activities','Actividades','fa-list-check'],['students','Alumnos','fa-users']];root.innerHTML=tabs.map(([k,l,i])=>`<button onclick="setInstructorTabV50('${k}')" class="px-4 py-2.5 rounded-xl text-xs font-bold ${instructorTabV50===k?'bg-lutmin-dark text-white':'text-slate-600 hover:bg-slate-50'}"><i class="fa-solid ${i} mr-2"></i>${l}</button>`).join('');}
function setInstructorTabV50(tab){instructorTabV50=tab;renderInstructorPortalV50();}
async function loadInstructorPortalV50(){if(!supabaseClient||currentLutminUser?.role!=='instructor')return;const root=document.getElementById('instructorBodyV50');if(root)root.innerHTML='<div class="rounded-3xl bg-white border border-slate-100 p-6 text-sm text-slate-500"><i class="fa-solid fa-spinner fa-spin mr-2"></i>Cargando portal docente...</div>';const {data,error}=await supabaseClient.rpc('instructor_dashboard_v50');if(error){console.error('Portal Docente V5',error);if(root)root.innerHTML='<div class="rounded-2xl bg-amber-50 border border-amber-100 p-4 text-sm text-amber-800">No pude abrir el Portal Docente. Verificá que tengas al menos una comisión asignada o contactá a Administración.</div>';return;}instructorPortalV50=data||{profile:null,summary:{},groups:[]};renderInstructorPortalV50();}
function renderInstructorPortalV50(){renderInstructorSummaryV50();renderInstructorTabsV50();const root=document.getElementById('instructorBodyV50');if(!root)return;if(instructorTabV50==='agenda')return renderInstructorAgendaV50(root);if(instructorTabV50==='activities')return renderInstructorActivitiesV50(root);if(instructorTabV50==='students')return renderInstructorStudentsV50(root);renderInstructorOverviewV50(root);}
function allInstructorSessionsV50(){const out=[];for(const g of instructorPortalV50.groups||[])for(const s of g.sessions||[])out.push({...s,group:g});return out.sort((a,b)=>`${a.session_date||''} ${a.start_time||''}`.localeCompare(`${b.session_date||''} ${b.start_time||''}`));}
function renderInstructorOverviewV50(root){const groups=instructorPortalV50.groups||[];const upcoming=allInstructorSessionsV50().filter(s=>String(s.session_date||'')>=new Date().toISOString().slice(0,10));root.innerHTML=`<div class="grid xl:grid-cols-[1.1fr_.9fr] gap-5"><div class="space-y-3">${groups.length?groups.map(g=>{const next=(g.sessions||[]).filter(s=>String(s.session_date||'')>=new Date().toISOString().slice(0,10)).sort((a,b)=>String(a.session_date).localeCompare(String(b.session_date)))[0];const pending=(g.activities||[]).reduce((n,a)=>n+Number(a.pending_reviews||0),0);return `<div class="bg-white rounded-3xl border border-slate-100 p-5 sm:p-6"><div class="flex flex-col md:flex-row md:items-start md:justify-between gap-3"><div><div class="flex flex-wrap gap-2"><span class="px-2.5 py-1 rounded-full bg-emerald-50 text-emerald-700 text-[10px] font-bold">${g.assignment_role==='assistant'?'ASISTENTE':'DOCENTE PRINCIPAL'}</span>${g.company_name?`<span class="px-2.5 py-1 rounded-full bg-slate-100 text-slate-600 text-[10px] font-bold">${escapeHtml(g.company_name)}</span>`:''}</div><h3 class="mt-2 text-lg font-black text-lutmin-dark">${escapeHtml(g.name)}</h3><p class="mt-1 text-xs text-slate-500">${escapeHtml(g.course_title||'Curso')} · ${(g.members||[]).length} alumno(s)</p></div><div class="flex gap-2"><button onclick="instructorTabV50='agenda';renderInstructorPortalV50()" class="px-3 py-2 rounded-xl bg-blue-50 text-blue-700 text-xs font-bold">Agenda</button><button onclick="instructorTabV50='activities';renderInstructorPortalV50()" class="px-3 py-2 rounded-xl bg-emerald-50 text-emerald-700 text-xs font-bold">Actividades</button></div></div><div class="mt-4 grid sm:grid-cols-2 gap-3"><div class="rounded-2xl bg-slate-50 p-4"><p class="text-[10px] uppercase font-bold text-slate-400">Próxima jornada</p><p class="mt-1 text-sm font-extrabold text-lutmin-dark">${next?`${v50Date(next.session_date)}${next.start_time?' · '+v50Time(next.start_time):''}`:'Sin fecha programada'}</p>${next?`<p class="mt-1 text-[10px] text-slate-500">${escapeHtml(next.title||'Jornada')}</p>`:''}</div><div class="rounded-2xl bg-slate-50 p-4"><p class="text-[10px] uppercase font-bold text-slate-400">Entregas a revisar</p><p class="mt-1 text-2xl font-black ${pending?'text-amber-600':'text-emerald-600'}">${pending}</p></div></div></div>`}).join(''):'<div class="bg-white rounded-3xl border border-slate-100 p-6 text-sm text-slate-500">Todavía no tenés comisiones asignadas.</div>'}</div><div class="bg-white rounded-3xl border border-slate-100 overflow-hidden"><div class="p-5 border-b border-slate-100"><h3 class="font-extrabold text-lutmin-dark">Próximas jornadas</h3><p class="text-xs text-slate-500">Agenda combinada de todas tus comisiones.</p></div><div class="divide-y divide-slate-100">${upcoming.length?upcoming.slice(0,8).map(s=>`<div class="p-4"><p class="text-[10px] font-bold text-emerald-600">${v50Date(s.session_date)}${s.start_time?' · '+v50Time(s.start_time):''}</p><p class="mt-1 text-sm font-extrabold text-lutmin-dark">${escapeHtml(s.title||'Jornada')}</p><p class="mt-1 text-[10px] text-slate-500">${escapeHtml(s.group.name)} · ${escapeHtml(s.group.course_title||'Curso')}</p></div>`).join(''):'<div class="p-6 text-sm text-slate-500">No hay jornadas próximas.</div>'}</div></div></div>`;}
function renderInstructorAgendaV50(root){const sessions=allInstructorSessionsV50();root.innerHTML=`<div class="flex justify-end mb-4"><button onclick="openInstructorSessionModalV50()" class="px-4 py-2.5 rounded-xl bg-emerald-600 text-white text-xs font-extrabold"><i class="fa-solid fa-plus mr-2"></i>Nueva jornada</button></div><div class="space-y-3">${sessions.length?sessions.map(s=>{const members=s.group.members||[],att=s.attendance||[],marked=att.filter(a=>a.status&&a.status!=='pending').length,ok=att.filter(a=>['present','late'].includes(a.status)).length,pct=marked?Math.round(ok*100/marked):null;const active=s.checkin?.active===true;return `<div class="bg-white rounded-3xl border border-slate-100 p-5"><div class="flex flex-col xl:flex-row xl:items-center xl:justify-between gap-4"><div><div class="flex flex-wrap gap-2"><span class="px-2 py-1 rounded-full bg-emerald-50 text-emerald-700 text-[10px] font-bold">${v50Date(s.session_date)}${s.start_time?' · '+v50Time(s.start_time):''}</span><span class="px-2 py-1 rounded-full bg-slate-100 text-slate-600 text-[10px] font-bold">${escapeHtml(s.group.name)}</span>${active?'<span class="px-2 py-1 rounded-full bg-green-100 text-green-700 text-[10px] font-black animate-pulse">CHECK-IN ABIERTO</span>':''}</div><h3 class="mt-2 font-extrabold text-lutmin-dark">${escapeHtml(s.title||'Jornada')}</h3><p class="mt-1 text-xs text-slate-500">${escapeHtml(s.group.course_title||'Curso')}${s.location?' · '+escapeHtml(s.location):''}</p><p class="mt-1 text-[10px] text-slate-400">Asistencia: ${pct===null?'sin marcar':pct+'%'} · ${marked}/${members.length} registrados</p></div><div class="flex flex-wrap gap-2"><button onclick="openInstructorAttendanceV50('${s.id}')" class="px-3 py-2 rounded-xl bg-lutmin-dark text-white text-xs font-bold">Asistencia</button>${active?`<button onclick="showExistingCheckinV50('${s.id}')" class="px-3 py-2 rounded-xl bg-green-50 text-green-700 text-xs font-bold">Ver código</button><button onclick="closeInstructorCheckinV50('${s.id}')" class="px-3 py-2 rounded-xl bg-red-50 text-red-700 text-xs font-bold">Cerrar check-in</button>`:`<button onclick="openInstructorCheckinV50('${s.id}')" class="px-3 py-2 rounded-xl bg-emerald-50 text-emerald-700 text-xs font-bold"><i class="fa-solid fa-qrcode mr-1"></i>Abrir check-in</button>`}${s.meeting_url?`<a href="${escapeHtml(s.meeting_url)}" target="_blank" rel="noopener" class="px-3 py-2 rounded-xl bg-blue-50 text-blue-700 text-xs font-bold">Reunión</a>`:''}</div></div></div>`}).join(''):'<div class="bg-white rounded-3xl border border-slate-100 p-6 text-sm text-slate-500">Todavía no hay jornadas. Creá la primera desde este portal.</div>'}</div>`;}
function renderInstructorActivitiesV50(root){const groups=instructorPortalV50.groups||[];root.innerHTML=`<div class="flex justify-end mb-4"><button onclick="openInstructorActivityModalV50()" class="px-4 py-2.5 rounded-xl bg-emerald-600 text-white text-xs font-extrabold"><i class="fa-solid fa-plus mr-2"></i>Nueva actividad</button></div><div class="space-y-5">${groups.map(g=>`<div class="bg-white rounded-3xl border border-slate-100 overflow-hidden"><div class="p-5 border-b border-slate-100"><p class="text-[10px] uppercase font-bold text-emerald-600">${escapeHtml(g.course_title||'Curso')}</p><h3 class="mt-1 font-extrabold text-lutmin-dark">${escapeHtml(g.name)}</h3></div><div class="divide-y divide-slate-100">${(g.activities||[]).length?(g.activities||[]).map(a=>{const due=v50DueMeta(a.due_at);return `<div class="p-4 flex flex-col lg:flex-row lg:items-center lg:justify-between gap-3"><div><div class="flex flex-wrap gap-2"><span class="px-2 py-1 rounded-full ${a.published?'bg-emerald-50 text-emerald-700':'bg-slate-100 text-slate-500'} text-[9px] font-bold">${a.published?'PUBLICADA':'BORRADOR'}</span>${a.required?'<span class="px-2 py-1 rounded-full bg-blue-50 text-blue-700 text-[9px] font-bold">OBLIGATORIA</span>':''}</div><p class="mt-2 text-sm font-extrabold text-lutmin-dark">${escapeHtml(a.title)}</p><p class="mt-1 text-[10px] ${due.cls}">${escapeHtml(due.label)} · ${Number(a.submission_count||0)} entrega(s) · ${Number(a.pending_reviews||0)} a revisar</p></div><div class="flex gap-2"><button onclick="openInstructorActivityModalV50('${a.id}')" class="px-3 py-2 rounded-xl bg-slate-100 text-xs font-bold">Editar</button><button onclick="openInstructorSubmissionsV50('${a.id}')" class="px-3 py-2 rounded-xl bg-lutmin-dark text-white text-xs font-bold">Entregas ${Number(a.pending_reviews||0)?'('+Number(a.pending_reviews||0)+')':''}</button></div></div>`}).join(''):'<div class="p-6 text-sm text-slate-500">Sin actividades todavía.</div>'}</div></div>`).join('')||'<div class="bg-white rounded-3xl border border-slate-100 p-6 text-sm text-slate-500">Necesitás una comisión asignada para crear actividades.</div>'}</div>`;}
function renderInstructorStudentsV50(root){const groups=instructorPortalV50.groups||[];root.innerHTML=`<div class="grid xl:grid-cols-2 gap-5">${groups.map(g=>`<div class="bg-white rounded-3xl border border-slate-100 overflow-hidden"><div class="p-5 border-b border-slate-100"><p class="text-[10px] uppercase font-bold text-emerald-600">${escapeHtml(g.course_title||'Curso')}</p><h3 class="mt-1 font-extrabold text-lutmin-dark">${escapeHtml(g.name)}</h3><p class="text-xs text-slate-500">${(g.members||[]).length} participantes</p></div><div class="divide-y divide-slate-100">${(g.members||[]).map(m=>{const pct=v50AttendancePct(g,m.user_id);return `<div class="p-4 flex items-center justify-between gap-3"><div><p class="text-sm font-extrabold text-lutmin-dark">${escapeHtml(m.full_name||m.email||'Alumno')}</p><p class="text-[10px] text-slate-400">${escapeHtml(m.email||'')}</p></div><div class="text-right"><p class="text-lg font-black ${pct===null?'text-slate-400':pct>=80?'text-emerald-600':'text-amber-600'}">${pct===null?'—':pct+'%'}</p><p class="text-[9px] text-slate-400">asistencia</p></div></div>`}).join('')||'<div class="p-6 text-sm text-slate-500">Sin alumnos.</div>'}</div></div>`).join('')||'<div class="xl:col-span-2 bg-white rounded-3xl border border-slate-100 p-6 text-sm text-slate-500">No hay comisiones asignadas.</div>'}</div>`;}

// ---------------------------------------------------------
// Modales docentes
// ---------------------------------------------------------
function ensureV50Modal(id,max='max-w-3xl'){let m=document.getElementById(id);if(m)return m;m=document.createElement('div');m.id=id;m.className='hidden fixed inset-0 z-[190] bg-slate-950/80 backdrop-blur-md p-2 sm:p-4 items-center justify-center';m.innerHTML=`<div class="w-full ${max} bg-white rounded-[2rem] shadow-2xl max-h-[95vh] overflow-y-auto modal-scroll relative"><button data-v50-close class="absolute right-4 top-4 z-10 w-10 h-10 rounded-full bg-slate-100 text-slate-500"><i class="fa-solid fa-xmark"></i></button><div data-v50-body class="p-6 sm:p-8"></div></div>`;m.querySelector('[data-v50-close]').onclick=()=>hideV50Modal(id);document.body.appendChild(m);return m;}
function showV50Modal(id){const m=document.getElementById(id);if(!m)return;m.classList.remove('hidden');m.classList.add('flex');document.body.classList.add('overflow-hidden');}
function hideV50Modal(id){const m=document.getElementById(id);if(!m)return;m.classList.add('hidden');m.classList.remove('flex');if(!document.querySelector('.fixed:not(.hidden)[id$="Modal"]'))document.body.classList.remove('overflow-hidden');}

function openInstructorSessionModalV50(){const groups=instructorPortalV50.groups||[];if(!groups.length)return showToast('No tenés comisiones asignadas.');const m=ensureV50Modal('instructorSessionModalV50','max-w-xl'),b=m.querySelector('[data-v50-body]');b.innerHTML=`<p class="text-[10px] uppercase tracking-widest font-extrabold text-emerald-600">Portal Docente</p><h3 class="mt-2 text-xl font-black text-lutmin-dark">Nueva jornada</h3><form onsubmit="saveInstructorSessionV50(event)" class="mt-5 space-y-3"><select id="v50SessionGroup" required class="w-full px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm">${groups.map(g=>`<option value="${g.id}">${escapeHtml(g.name)} · ${escapeHtml(g.course_title||'Curso')}</option>`).join('')}</select><input id="v50SessionTitle" required class="w-full px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm" placeholder="Nombre de la jornada"><div class="grid grid-cols-3 gap-2"><input id="v50SessionDate" type="date" required value="${new Date().toISOString().slice(0,10)}" class="px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm"><input id="v50SessionStart" type="time" class="px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm"><input id="v50SessionEnd" type="time" class="px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm"></div><input id="v50SessionLocation" class="w-full px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm" placeholder="Lugar"><input id="v50SessionUrl" type="url" class="w-full px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm" placeholder="Enlace de reunión (opcional)"><textarea id="v50SessionNotes" rows="3" class="w-full px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm" placeholder="Notas"></textarea><button class="w-full py-3 rounded-xl bg-emerald-600 text-white font-extrabold">Crear jornada</button></form>`;showV50Modal('instructorSessionModalV50');}
async function saveInstructorSessionV50(e){e.preventDefault();const {error}=await supabaseClient.rpc('instructor_add_session_v50',{p_group_id:document.getElementById('v50SessionGroup').value,p_title:document.getElementById('v50SessionTitle').value.trim(),p_session_date:document.getElementById('v50SessionDate').value,p_start_time:document.getElementById('v50SessionStart').value||null,p_end_time:document.getElementById('v50SessionEnd').value||null,p_location:document.getElementById('v50SessionLocation').value.trim()||null,p_meeting_url:document.getElementById('v50SessionUrl').value.trim()||null,p_notes:document.getElementById('v50SessionNotes').value.trim()||null});if(error)return showToast(error.message||'No pude crear la jornada.');hideV50Modal('instructorSessionModalV50');showToast('Jornada creada.');await loadInstructorPortalV50();instructorTabV50='agenda';renderInstructorPortalV50();}

function openInstructorAttendanceV50(sessionId){const s=v50SessionById(sessionId);if(!s)return;instructorActiveSessionV50=sessionId;const marks=new Map((s.attendance||[]).map(a=>[a.user_id,a]));const m=ensureV50Modal('instructorAttendanceModalV50','max-w-3xl'),b=m.querySelector('[data-v50-body]');b.innerHTML=`<p class="text-[10px] uppercase tracking-widest font-extrabold text-emerald-600">Asistencia</p><h3 class="mt-2 text-xl font-black text-lutmin-dark">${escapeHtml(s.title||'Jornada')}</h3><p class="mt-1 text-xs text-slate-500">${escapeHtml(s.group.name)} · ${v50Date(s.session_date)}</p><div class="mt-4 flex flex-wrap gap-2"><button type="button" onclick="setAllInstructorAttendanceV50('present')" class="px-3 py-2 rounded-xl bg-emerald-50 text-emerald-700 text-xs font-bold">Todos presentes</button><button type="button" onclick="setAllInstructorAttendanceV50('pending')" class="px-3 py-2 rounded-xl bg-slate-100 text-slate-600 text-xs font-bold">Limpiar</button></div><div class="mt-4 space-y-2">${(s.group.members||[]).map(x=>{const a=marks.get(x.user_id);return `<div class="rounded-xl border border-slate-100 p-3 grid sm:grid-cols-[1fr_180px] gap-3 items-center"><div><p class="text-xs font-extrabold text-lutmin-dark">${escapeHtml(x.full_name||x.email||'Alumno')}</p><p class="text-[10px] text-slate-400">${escapeHtml(x.email||'')}</p></div><select data-v50-att-user="${x.user_id}" class="px-3 py-2 rounded-xl border border-slate-200 text-xs"><option value="pending" ${!a||a.status==='pending'?'selected':''}>Pendiente</option><option value="present" ${a?.status==='present'?'selected':''}>Presente</option><option value="late" ${a?.status==='late'?'selected':''}>Tarde</option><option value="absent" ${a?.status==='absent'?'selected':''}>Ausente</option><option value="justified" ${a?.status==='justified'?'selected':''}>Justificado</option></select></div>`}).join('')||'<p class="text-sm text-slate-500">No hay alumnos en esta comisión.</p>'}</div><button onclick="saveInstructorAttendanceV50()" class="mt-5 w-full py-3 rounded-xl bg-lutmin-dark text-white font-extrabold">Guardar asistencia</button>`;showV50Modal('instructorAttendanceModalV50');}
function setAllInstructorAttendanceV50(status){document.querySelectorAll('[data-v50-att-user]').forEach(x=>x.value=status);}
async function saveInstructorAttendanceV50(){const records=[...document.querySelectorAll('[data-v50-att-user]')].map(x=>({user_id:x.dataset.v50AttUser,status:x.value,notes:null}));const {data,error}=await supabaseClient.rpc('instructor_save_attendance_v50',{p_session_id:instructorActiveSessionV50,p_records:records});if(error)return showToast(error.message||'No pude guardar la asistencia.');hideV50Modal('instructorAttendanceModalV50');showToast(`Asistencia guardada · ${Number(data||0)} registros.`);await loadInstructorPortalV50();instructorTabV50='agenda';renderInstructorPortalV50();}

async function openInstructorCheckinV50(sessionId){const minutes=Number(prompt('¿Cuántos minutos querés dejar abierto el check-in?',20)||20);if(!minutes)return;const {data,error}=await supabaseClient.rpc('instructor_open_checkin_v50',{p_session_id:sessionId,p_minutes:minutes});if(error)return showToast(error.message||'No pude abrir el check-in.');await showCheckinModalV50(data);await loadInstructorPortalV50();instructorTabV50='agenda';renderInstructorPortalV50();}
async function showExistingCheckinV50(sessionId){const s=v50SessionById(sessionId);if(!s?.checkin)return;await showCheckinModalV50({session_id:sessionId,code:s.checkin.code,closes_at:s.checkin.closes_at});}
async function showCheckinModalV50(data){const m=ensureV50Modal('instructorCheckinModalV50','max-w-lg'),b=m.querySelector('[data-v50-body]');b.innerHTML=`<div class="text-center"><p class="text-[10px] uppercase tracking-widest font-extrabold text-emerald-600">Check-in abierto</p><h3 class="mt-2 text-xl font-black text-lutmin-dark">Mostrá este código a los alumnos</h3><div class="mt-5 text-4xl sm:text-5xl font-black tracking-[.18em] text-lutmin-dark">${escapeHtml(data.code||'')}</div><p class="mt-2 text-xs text-slate-500">Disponible hasta ${v50DateTime(data.closes_at)}</p><div id="v50CheckinQr" class="mt-5 flex justify-center"></div><p class="mt-3 text-[10px] text-slate-400">También pueden ingresar el código manualmente desde Actividades.</p></div>`;showV50Modal('instructorCheckinModalV50');try{await ensureQRCodeLib();const u=new URL(location.href);u.searchParams.set('checkin',data.code||'');u.hash='';const qr=document.getElementById('v50CheckinQr');if(qr){qr.innerHTML='';new QRCode(qr,{text:u.toString(),width:170,height:170,correctLevel:QRCode.CorrectLevel.M});}}catch(_){}}
async function closeInstructorCheckinV50(sessionId){const {error}=await supabaseClient.rpc('instructor_close_checkin_v50',{p_session_id:sessionId});if(error)return showToast(error.message||'No pude cerrar el check-in.');showToast('Check-in cerrado.');await loadInstructorPortalV50();instructorTabV50='agenda';renderInstructorPortalV50();}

function openInstructorActivityModalV50(activityId=null){const groups=instructorPortalV50.groups||[];if(!groups.length)return showToast('No tenés comisiones asignadas.');const item=activityId?v50ActivityById(activityId):null;const m=ensureV50Modal('instructorActivityModalV50','max-w-xl'),b=m.querySelector('[data-v50-body]');b.innerHTML=`<p class="text-[10px] uppercase tracking-widest font-extrabold text-emerald-600">Actividad práctica</p><h3 class="mt-2 text-xl font-black text-lutmin-dark">${item?'Editar actividad':'Nueva actividad'}</h3><form onsubmit="saveInstructorActivityV50(event)" class="mt-5 space-y-3"><input id="v50ActivityId" type="hidden" value="${item?.id||''}"><select id="v50ActivityGroup" required class="w-full px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm" ${item?'disabled':''}>${groups.map(g=>`<option value="${g.id}" ${item?.group?.id===g.id?'selected':''}>${escapeHtml(g.name)} · ${escapeHtml(g.course_title||'Curso')}</option>`).join('')}</select><input id="v50ActivityTitle" required value="${escapeHtml(item?.title||'')}" class="w-full px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm" placeholder="Título"><textarea id="v50ActivityInstructions" rows="5" class="w-full px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm" placeholder="Consigna / instrucciones">${escapeHtml(item?.instructions||'')}</textarea><div class="grid sm:grid-cols-2 gap-2"><input id="v50ActivityDue" type="datetime-local" value="${item?.due_at?new Date(item.due_at).toISOString().slice(0,16):''}" class="px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm"><input id="v50ActivityMax" type="number" min="1" max="1000" step="1" value="${Number(item?.max_score||100)}" class="px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm" placeholder="Puntaje máximo"></div><div class="grid sm:grid-cols-2 gap-2 text-xs"><label class="rounded-xl bg-slate-50 p-3 flex items-center gap-2"><input id="v50ActivityRequired" type="checkbox" ${item?.required===false?'':'checked'}> Obligatoria</label><label class="rounded-xl bg-slate-50 p-3 flex items-center gap-2"><input id="v50ActivityPublished" type="checkbox" ${item?.published===false?'':'checked'}> Publicada</label></div><button class="w-full py-3 rounded-xl bg-emerald-600 text-white font-extrabold">Guardar actividad</button></form>`;showV50Modal('instructorActivityModalV50');}
async function saveInstructorActivityV50(e){e.preventDefault();const id=document.getElementById('v50ActivityId').value||null;const group=id?v50ActivityById(id)?.group?.id:document.getElementById('v50ActivityGroup').value;const due=document.getElementById('v50ActivityDue').value;const {error}=await supabaseClient.rpc('instructor_save_activity_v50',{p_id:id,p_group_id:group,p_title:document.getElementById('v50ActivityTitle').value.trim(),p_instructions:document.getElementById('v50ActivityInstructions').value.trim()||null,p_due_at:due?new Date(due).toISOString():null,p_max_score:Number(document.getElementById('v50ActivityMax').value||100),p_required:document.getElementById('v50ActivityRequired').checked,p_published:document.getElementById('v50ActivityPublished').checked});if(error)return showToast(error.message||'No pude guardar la actividad.');hideV50Modal('instructorActivityModalV50');showToast('Actividad guardada.');await loadInstructorPortalV50();instructorTabV50='activities';renderInstructorPortalV50();}

async function openInstructorSubmissionsV50(activityId){instructorActiveActivityV50=activityId;const m=ensureV50Modal('instructorSubmissionsModalV50','max-w-5xl'),b=m.querySelector('[data-v50-body]');b.innerHTML='<p class="text-sm text-slate-500"><i class="fa-solid fa-spinner fa-spin mr-2"></i>Cargando entregas...</p>';showV50Modal('instructorSubmissionsModalV50');const {data,error}=await supabaseClient.rpc('instructor_activity_submissions_v50',{p_activity_id:activityId});if(error){b.innerHTML=`<p class="text-sm text-red-600">${escapeHtml(error.message||'No pude cargar las entregas.')}</p>`;return;}const a=data?.activity||{},rows=data?.rows||[];b.innerHTML=`<p class="text-[10px] uppercase tracking-widest font-extrabold text-emerald-600">Corrección</p><h3 class="mt-2 text-2xl font-black text-lutmin-dark">${escapeHtml(a.title||'Actividad')}</h3><p class="mt-1 text-xs text-slate-500">Puntaje máximo: ${Number(a.max_score||100)}</p><div class="mt-5 space-y-3">${rows.map(r=>`<div class="rounded-2xl border ${r.status==='submitted'?'border-amber-200 bg-amber-50/30':'border-slate-100'} p-4"><div class="flex flex-col lg:flex-row lg:items-start lg:justify-between gap-3"><div><p class="font-extrabold text-sm text-lutmin-dark">${escapeHtml(r.full_name||r.email||'Alumno')}</p><p class="text-[10px] text-slate-400">${escapeHtml(r.email||'')} · ${r.status==='missing'?'Sin entrega':r.status==='reviewed'?'Revisada':r.status==='returned'?'Devuelta':'Entregada'}</p>${r.submitted_at?`<p class="text-[10px] text-slate-400">${v50DateTime(r.submitted_at)}</p>`:''}</div>${r.status!=='missing'?`<span class="px-2.5 py-1 rounded-full text-[10px] font-bold ${r.status==='reviewed'?'bg-emerald-50 text-emerald-700':r.status==='returned'?'bg-red-50 text-red-700':'bg-amber-50 text-amber-700'}">${escapeHtml(String(r.status).toUpperCase())}</span>`:''}</div>${r.answer_text?`<div class="mt-3 rounded-xl bg-white border border-slate-100 p-3 text-xs text-slate-700 whitespace-pre-wrap">${escapeHtml(r.answer_text)}</div>`:''}${r.external_url?`<a href="${escapeHtml(r.external_url)}" target="_blank" rel="noopener" class="mt-2 inline-flex text-xs font-bold text-blue-600"><i class="fa-solid fa-arrow-up-right-from-square mr-2"></i>Abrir entrega</a>`:''}${r.submission_id?`<div class="mt-3 grid lg:grid-cols-[120px_1fr_auto_auto] gap-2"><input id="v50Score_${r.submission_id}" type="number" min="0" max="${Number(a.max_score||100)}" step="0.5" value="${r.score??''}" class="px-3 py-2 rounded-xl border border-slate-200 text-xs" placeholder="Puntaje"><input id="v50Feedback_${r.submission_id}" value="${escapeHtml(r.feedback||'')}" class="px-3 py-2 rounded-xl border border-slate-200 text-xs" placeholder="Devolución"><button onclick="reviewSubmissionV50('${r.submission_id}','reviewed',${Number(a.max_score||100)})" class="px-3 py-2 rounded-xl bg-emerald-600 text-white text-xs font-bold">Aprobar devolución</button><button onclick="reviewSubmissionV50('${r.submission_id}','returned',${Number(a.max_score||100)})" class="px-3 py-2 rounded-xl bg-red-50 text-red-700 text-xs font-bold">Devolver</button></div>`:''}</div>`).join('')||'<p class="text-sm text-slate-500">No hay alumnos.</p>'}</div>`;}
async function reviewSubmissionV50(id,status,max){const scoreEl=document.getElementById(`v50Score_${id}`),feedback=document.getElementById(`v50Feedback_${id}`)?.value||null;const score=scoreEl?.value===''?null:Number(scoreEl.value);if(score!=null&&(score<0||score>max))return showToast(`El puntaje debe estar entre 0 y ${max}.`);const {error}=await supabaseClient.rpc('instructor_review_submission_v50',{p_submission_id:id,p_score:score,p_feedback:feedback,p_status:status});if(error)return showToast(error.message||'No pude guardar la devolución.');showToast(status==='returned'?'Entrega devuelta al alumno.':'Devolución guardada.');await openInstructorSubmissionsV50(instructorActiveActivityV50);await loadInstructorPortalV50();}

// ---------------------------------------------------------
// ALUMNO · actividades y check-in
// ---------------------------------------------------------
async function loadStudentActivitiesV50(){if(!supabaseClient||currentLutminUser?.role!=='student')return;const root=document.getElementById('studentActivitiesBodyV50');if(root)root.innerHTML='<div class="rounded-3xl bg-white border border-slate-100 p-6 text-sm text-slate-500"><i class="fa-solid fa-spinner fa-spin mr-2"></i>Cargando actividades...</div>';const {data,error}=await supabaseClient.rpc('my_training_activities_v50');if(error){console.error('Actividades V5',error);if(root)root.innerHTML='<div class="rounded-2xl bg-amber-50 border border-amber-100 p-4 text-sm text-amber-800">El módulo de actividades todavía no está habilitado. Contactá a Administración.</div>';return;}studentActivitiesV50=data||{summary:{},activities:[]};renderStudentActivitiesV50();}
function renderStudentActivitiesV50(){const root=document.getElementById('studentActivitiesBodyV50');if(!root)return;const s=studentActivitiesV50.summary||{},rows=studentActivitiesV50.activities||[];root.innerHTML=`<div class="grid grid-cols-3 gap-3"><div class="bg-white rounded-2xl border border-slate-100 p-4"><p class="text-[10px] uppercase font-bold text-slate-400">Pendientes</p><p class="mt-1 text-2xl font-black text-amber-600">${Number(s.pending||0)}</p></div><div class="bg-white rounded-2xl border border-slate-100 p-4"><p class="text-[10px] uppercase font-bold text-slate-400">Revisadas</p><p class="mt-1 text-2xl font-black text-emerald-600">${Number(s.reviewed||0)}</p></div><div class="bg-white rounded-2xl border border-slate-100 p-4"><p class="text-[10px] uppercase font-bold text-slate-400">Vencen ≤7 días</p><p class="mt-1 text-2xl font-black text-red-600">${Number(s.due_soon||0)}</p></div></div><div class="mt-5 space-y-3">${rows.length?rows.map(a=>{const sub=a.submission,due=v50DueMeta(a.due_at);const status=!sub?'pending':sub.status;return `<div class="bg-white rounded-3xl border ${status==='returned'?'border-red-100':status==='submitted'?'border-amber-100':'border-slate-100'} p-5"><div class="flex flex-col lg:flex-row lg:items-start lg:justify-between gap-4"><div><div class="flex flex-wrap gap-2"><span class="px-2 py-1 rounded-full bg-blue-50 text-blue-700 text-[9px] font-bold">${escapeHtml(a.course_title||'Curso')}</span><span class="px-2 py-1 rounded-full bg-slate-100 text-slate-600 text-[9px] font-bold">${escapeHtml(a.group_name||'Comisión')}</span>${a.required?'<span class="px-2 py-1 rounded-full bg-violet-50 text-violet-700 text-[9px] font-bold">OBLIGATORIA</span>':''}</div><h3 class="mt-2 text-lg font-black text-lutmin-dark">${escapeHtml(a.title)}</h3><p class="mt-1 text-sm text-slate-600 whitespace-pre-wrap">${escapeHtml(a.instructions||'Sin instrucciones adicionales.')}</p><p class="mt-2 text-[10px] ${due.cls}">${escapeHtml(due.label)} · máximo ${Number(a.max_score||100)} puntos</p></div><div class="lg:text-right">${status==='reviewed'?`<p class="text-2xl font-black text-emerald-600">${sub.score==null?'Revisada':Number(sub.score).toLocaleString('es-AR')}</p><p class="text-[10px] text-slate-400">${sub.score==null?'Sin puntaje':`de ${Number(a.max_score||100)}`}</p>`:status==='submitted'?'<span class="px-3 py-1.5 rounded-full bg-amber-50 text-amber-700 text-[10px] font-extrabold">EN REVISIÓN</span>':status==='returned'?'<span class="px-3 py-1.5 rounded-full bg-red-50 text-red-700 text-[10px] font-extrabold">DEVUELTA</span>':'<span class="px-3 py-1.5 rounded-full bg-slate-100 text-slate-600 text-[10px] font-extrabold">PENDIENTE</span>'}</div></div>${sub?.feedback?`<div class="mt-4 rounded-xl bg-emerald-50 border border-emerald-100 p-3"><p class="text-[10px] uppercase font-bold text-emerald-600">Devolución docente</p><p class="mt-1 text-xs text-emerald-900 whitespace-pre-wrap">${escapeHtml(sub.feedback)}</p></div>`:''}<div class="mt-4 flex flex-wrap gap-2"><button onclick="openStudentSubmissionV50('${a.id}')" class="px-3 py-2 rounded-xl bg-lutmin-dark text-white text-xs font-bold">${sub?'Ver / actualizar entrega':'Entregar actividad'}</button>${sub?.external_url?`<a href="${escapeHtml(sub.external_url)}" target="_blank" rel="noopener" class="px-3 py-2 rounded-xl bg-blue-50 text-blue-700 text-xs font-bold">Abrir enlace enviado</a>`:''}</div></div>`}).join(''):'<div class="bg-white rounded-3xl border border-slate-100 p-8 text-center"><div class="w-12 h-12 rounded-2xl bg-emerald-50 text-emerald-600 flex items-center justify-center mx-auto"><i class="fa-solid fa-circle-check"></i></div><p class="mt-3 font-extrabold text-lutmin-dark">No tenés actividades asignadas</p><p class="mt-1 text-sm text-slate-500">Cuando un docente publique una actividad aparecerá acá.</p></div>'}</div>`;}
function studentActivityByIdV50(id){return (studentActivitiesV50.activities||[]).find(x=>x.id===id)}
function openStudentSubmissionV50(id){const a=studentActivityByIdV50(id);if(!a)return;const m=ensureV50Modal('studentSubmissionModalV50','max-w-xl'),b=m.querySelector('[data-v50-body]'),s=a.submission||{};b.innerHTML=`<p class="text-[10px] uppercase tracking-widest font-extrabold text-emerald-600">Entrega</p><h3 class="mt-2 text-xl font-black text-lutmin-dark">${escapeHtml(a.title)}</h3><p class="mt-1 text-xs text-slate-500">${escapeHtml(a.course_title||'Curso')} · ${escapeHtml(a.group_name||'Comisión')}</p><form onsubmit="submitStudentActivityV50(event,'${a.id}')" class="mt-5 space-y-3"><textarea id="v50StudentAnswer" rows="7" class="w-full px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm" placeholder="Escribí tu respuesta, explicación o detalle de la entrega">${escapeHtml(s.answer_text||'')}</textarea><input id="v50StudentUrl" type="url" value="${escapeHtml(s.external_url||'')}" class="w-full px-3 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm" placeholder="Enlace a Drive, video, documento o evidencia (opcional)"><p class="text-[10px] text-slate-400">Podés enviar texto, un enlace o ambos.</p><button class="w-full py-3 rounded-xl bg-emerald-600 text-white font-extrabold">Enviar actividad</button></form>`;showV50Modal('studentSubmissionModalV50');}
async function submitStudentActivityV50(e,id){e.preventDefault();const answer=document.getElementById('v50StudentAnswer').value.trim(),url=document.getElementById('v50StudentUrl').value.trim();if(!answer&&!url)return showToast('Escribí una respuesta o agregá un enlace.');const {error}=await supabaseClient.rpc('submit_training_activity_v50',{p_activity_id:id,p_answer_text:answer||null,p_external_url:url||null});if(error)return showToast(error.message||'No pude enviar la actividad.');hideV50Modal('studentSubmissionModalV50');showToast('Actividad enviada al docente.');await loadStudentActivitiesV50();}
async function performStudentCheckinV50(code){const clean=String(code||'').trim().toUpperCase();if(!clean)return showToast('Ingresá el código de check-in.');const {data,error}=await supabaseClient.rpc('student_checkin_v50',{p_code:clean});if(error)return showToast(error.message||'No pude registrar la asistencia.');showToast(`Asistencia registrada · ${data?.title||'jornada'}.`);const u=new URL(location.href);u.searchParams.delete('checkin');history.replaceState({},'',u.toString());const input=document.getElementById('studentCheckinCodeV50');if(input)input.value='';}
async function studentCheckinV50(e){e.preventDefault();await performStudentCheckinV50(document.getElementById('studentCheckinCodeV50')?.value||'');}
async function processPendingCheckinV50(){if(currentLutminUser?.role!=='student')return;const code=new URL(location.href).searchParams.get('checkin');if(!code)return;goToCampusTab('activities');const input=document.getElementById('studentCheckinCodeV50');if(input)input.value=code.toUpperCase();await performStudentCheckinV50(code);await loadStudentActivitiesV50();}

// ---------------------------------------------------------
// Integración con Administración existente
// ---------------------------------------------------------
const _loadAdminDataV50=loadAdminData;
loadAdminData=async function(){const r=await _loadAdminDataV50.apply(this,arguments);if(currentLutminUser?.role==='admin'){initAdminInstructorV50();await loadAdminInstructorV50();}return r;};

function initV50(){
  if(currentLutminUser?.role==='admin'){initAdminInstructorV50();loadAdminInstructorV50();}
  if(currentLutminUser?.role==='instructor')loadInstructorPortalV50();
  if(currentLutminUser?.role==='student'&&new URL(location.href).searchParams.get('checkin'))processPendingCheckinV50();
}
document.addEventListener('DOMContentLoaded',()=>setTimeout(initV50,1150),{once:true});
